package com.yessteveskill.paper;
import com.yessteveattribute.core.runtime.*; import com.yessteveattribute.paper.PaperAttributeService; import io.lumine.mythic.api.adapters.AbstractEntity; import io.lumine.mythic.api.config.MythicLineConfig; import io.lumine.mythic.api.skills.*; import org.bukkit.entity.*; import java.util.Locale;
final class YsaDamageMechanic implements ITargetedEntitySkill { private final PaperAttributeService service; private final double multiplier; private final CombatDamageType type; YsaDamageMechanic(MythicLineConfig c,PaperAttributeService s){service=s;multiplier=c.getDouble("multiplier",1D);CombatDamageType t;try{t=CombatDamageType.valueOf(c.getString("type","composite").toUpperCase(Locale.ROOT));}catch(Exception e){t=CombatDamageType.COMPOSITE;}type=t;} @Override public SkillResult castAtEntity(SkillMetadata m,AbstractEntity t){AbstractEntity c=m.getCaster().getEntity();if(c==null||!c.isPlayer()||t==null||!t.isLiving())return SkillResult.INVALID_TARGET;LivingEntity victim=(LivingEntity)t.getBukkitEntity();Player attacker=(Player)c.getBukkitEntity();var result=service.calculate(attacker,victim,multiplier,java.util.concurrent.ThreadLocalRandom.current().nextDouble(),type);var applied=DamageApplication.apply(result.damage(),a->{victim.damage(a,attacker);return true;});return applied.status()==DamageApplication.Status.REJECTED?SkillResult.ERROR:SkillResult.SUCCESS;}}
